import {taskLabels,miles} from './domain.js?v=0.23.0';
import {cleanItems} from './order-care.js?v=0.23.0';
import {cloudScanToken} from './cloud-scan.js?v=0.23.0';
import {scannerDeviceToken} from './push.js?v=0.23.0';
const API='https://delivery-manager-reminders.tonykevinjr.workers.dev';
const hex=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
const b64=bytes=>btoa(String.fromCharCode(...bytes));const un64=text=>Uint8Array.from(atob(text),x=>x.charCodeAt(0));
const storeKey=mode=>'delivery-manager-dispatch-driver-'+mode;
export function dispatchConfig(mode){try{return JSON.parse(localStorage.getItem(storeKey(mode))||'null');}catch{return null;}}
export async function dispatchCall(path,body,token){const r=await fetch(API+'/dispatch/'+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(body||{}),cache:'no-store',signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Dispatch connection unavailable.');return data;}
export async function createDispatchPair(mode){const auth=scannerDeviceToken()||cloudScanToken();if(!auth)throw Error('Connect the ticket scanner or lock-screen reminders first, then pair Mike’s device.');let config=dispatchConfig(mode);if(!config){config={id:crypto.randomUUID(),driverToken:hex(),managerToken:hex(),key:b64(crypto.getRandomValues(new Uint8Array(32))),mode,connected:false};localStorage.setItem(storeKey(mode),JSON.stringify(config));}await dispatchCall('create',{id:config.id,driverToken:config.driverToken,managerToken:config.managerToken,mode,pushToken:scannerDeviceToken()},auth);config.connected=true;localStorage.setItem(storeKey(mode),JSON.stringify(config));return config;}
export function pairingCode(c){return 'DM1.'+b64(new TextEncoder().encode(JSON.stringify({id:c.id,token:c.managerToken,key:c.key,mode:c.mode})));}
export function parsePairingCode(text){try{if(!text.startsWith('DM1.'))throw Error();const c=JSON.parse(new TextDecoder().decode(un64(text.slice(4).trim())));if(!/^[a-f0-9-]{36}$/.test(c.id)||!/^[a-f0-9]{64}$/.test(c.token)||un64(c.key).length!==32||!['live','test'].includes(c.mode))throw Error();return c;}catch{throw Error('Paste the complete pairing code from the driver’s Settings.');}}
export async function disconnectDispatch(mode){const c=dispatchConfig(mode);if(c?.connected)await dispatchCall('disconnect',{},c.driverToken);localStorage.removeItem(storeKey(mode));}
export async function connectDispatchPush(mode){const c=dispatchConfig(mode);if(!c?.connected)throw Error('Pair a manager first.');return dispatchCall('push',{pushToken:scannerDeviceToken()},c.driverToken);}
export function cleanDispatch(value){if(['group','reorder','ready'].includes(value?.action)){if(value.version!==1||!['live','test'].includes(value.mode)||!Array.isArray(value.deliveryIds)||value.deliveryIds.length<(value.action==='group'?2:1)||value.deliveryIds.length>12||new Set(value.deliveryIds).size!==value.deliveryIds.length||value.deliveryIds.some(x=>typeof x!=='string'||x.length>100))throw Error('Choose two to twelve unstarted orders.');if(value.action==='reorder'&&(typeof value.batchId!=='string'||value.batchId.length>100||!value.batchId))throw Error('Choose an existing batch.');return {version:1,action:value.action,mode:value.mode,deliveryIds:value.deliveryIds,...(value.action==='reorder'?{batchId:value.batchId}:{}),...(value.action==='ready'&&value.hold===true?{hold:true}:{})};}if(value?.action&&value.action!=='orders')throw Error('Unsupported dispatch action.');if(value?.version!==1||!['live','test'].includes(value.mode)||!['single','batch'].includes(value.kind)||!Array.isArray(value.orders)||value.orders.length<1||value.orders.length>12)throw Error('Invalid dispatch contents.');const orders=value.orders.map(d=>{const text=(k,max)=>typeof d[k]==='string'?d[k].trim().slice(0,max):'';const x={name:text('name',100),phone:text('phone',40),address:text('address',350),ticket:text('ticket',30),notes:text('notes',2000),hasColdItems:d.hasColdItems,hasAlcohol:d.hasAlcohol,needsSignature:!!d.needsSignature,routeCustomized:d.routeCustomized===true,coldItemDetails:text('coldItemDetails',500),scheduledAt:d.scheduledAt||null,items:cleanItems(d.items),orderPlacedAt:typeof d.orderPlacedAt==='string'&&Number.isFinite(Date.parse(d.orderPlacedAt))?d.orderPlacedAt:null,addedAt:typeof d.addedAt==='string'&&Number.isFinite(Date.parse(d.addedAt))?d.addedAt:null};if(!x.address||typeof x.hasColdItems!=='boolean'||typeof x.hasAlcohol!=='boolean'||x.hasColdItems&&!x.coldItemDetails||x.scheduledAt&&(!Number.isFinite(Date.parse(x.scheduledAt))||typeof x.scheduledAt!=='string')||x.phone&&!/^\+?[\d ().-]{7,40}$/.test(x.phone))throw Error('Review the address, phone and required drink/alcohol choices before sending.');return x;});return {version:1,mode:value.mode,kind:value.kind,orders};}
const aad=(pair,id,mode)=>new TextEncoder().encode(`delivery-manager-dispatch-v1/${pair}/${id}/${mode}`);
export async function sealDispatch(config,payload,id=crypto.randomUUID()){const clean=cleanDispatch(payload);if(clean.mode!==config.mode)throw Error('Test and live dispatch cannot be mixed.');const iv=crypto.getRandomValues(new Uint8Array(12)),key=await crypto.subtle.importKey('raw',un64(config.key),'AES-GCM',false,['encrypt']);const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad(config.id,id,config.mode)},key,new TextEncoder().encode(JSON.stringify(clean)));if(ciphertext.byteLength>24000)throw Error('This addition is too large. Shorten its notes or split it into two sends.');return {id,mode:config.mode,iv:b64(iv),ciphertext:b64(new Uint8Array(ciphertext))};}
export async function openDispatch(config,packet){const key=await crypto.subtle.importKey('raw',un64(config.key),'AES-GCM',false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(packet.iv),additionalData:aad(config.id,packet.id,config.mode)},key,un64(packet.ciphertext));const value=cleanDispatch(JSON.parse(new TextDecoder().decode(plain)));if(value.mode!==config.mode)throw Error('Dispatch belongs to a different record mode.');return value;}
export const DISPATCH_COLORS=['orange','blue','purple','yellow'];
export function applyDispatch(state,packet,payload,mode,at=new Date().toISOString()){const clean=cleanDispatch(payload);if(clean.mode!==mode)throw Error('Dispatch belongs to a different record mode.');if(state.dispatchReceipts?.includes(packet.id)||state.shifts.some(s=>s.dispatchReceipts?.some(x=>x.id===packet.id)))return {duplicate:true};const shift=state.shifts.find(s=>s.status==='active');if(!shift)return {waiting:true};shift.dispatchReceipts??=[];if(clean.action==='ready')return markDispatchedReady(state,shift,packet,clean,at);if(clean.action==='reorder')return reorderDispatchedBatch(state,shift,packet,clean,at);if(clean.action==='group')return groupDispatchedOrders(state,shift,packet,clean,at);const addition=shift.dispatchReceipts.length+1,color=nextDispatchColor(state,shift.id),batchId=clean.kind==='batch'?`dispatch-${packet.id}`:null;clean.orders.forEach((d,i)=>state.deliveries.push({...d,id:`dispatch-${packet.id}-${i}`,shiftId:shift.id,customerId:null,enteredAt:d.addedAt&&Date.parse(d.addedAt)<=Date.parse(at)?d.addedAt:at,receivedAt:at,status:'pending',events:[{type:'dispatch-received',at,to:'pending'}],deliveryMode:batchId?'batch':'single',batchId,batchPosition:i,dispatchPairId:packet.pairId||null,dispatchId:packet.id,dispatchGroupId:packet.id,dispatchAddition:addition,dispatchColor:color,dispatchSource:'Mike',...(d.routeCustomized?{routeOrderSource:'manager'}:{})}));state.dispatchReceipts??=[];state.dispatchReceipts.push(packet.id);shift.dispatchReceipts.push({id:packet.id,addition,color,receivedAt:at});return {added:clean.orders.length,addition,color};}

export function nextDispatchColor(state,shiftId,excluding=[]){const skip=new Set(excluding),active=state.deliveries.filter(d=>d.shiftId===shiftId&&d.dispatchId&&!skip.has(d.id)&&!['delivered','canceled'].includes(d.status));if(!active.length)return 'orange';const latest=[...active].sort((a,b)=>(b.dispatchAddition||0)-(a.dispatchAddition||0))[0];return DISPATCH_COLORS[(DISPATCH_COLORS.indexOf(latest.dispatchColor)+1)%4];}
function groupDispatchedOrders(state,shift,packet,command,at){const orders=command.deliveryIds.map(id=>state.deliveries.find(d=>d.id===id)),invalid=orders.some(d=>!d||d.shiftId!==shift.id||!d.dispatchId||(packet.allowedDispatchIds&&!packet.allowedDispatchIds.includes(d.dispatchId))||d.batchId||!['pending','ready'].includes(d.status)||d.departedAt||state.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(d.id)));state.dispatchReceipts??=[];state.dispatchReceipts.push(packet.id);state.dispatchCommandResults??={};if(invalid){const message='Batch not created: an order is missing, already grouped, or its delivery has started.';state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'rejected',message,at};return {rejected:message};}const addition=shift.dispatchReceipts.length+1,color=nextDispatchColor(state,shift.id,command.deliveryIds),batchId='dispatch-'+packet.id;orders.forEach((d,i)=>Object.assign(d,{batchId,batchPosition:i,deliveryMode:'batch',routeCustomized:false,dispatchGroupId:packet.id,dispatchAddition:addition,dispatchColor:color}));shift.dispatchReceipts.push({id:packet.id,addition,color,receivedAt:at});state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'grouped',message:'Orders combined into a batch.',at};return {grouped:orders.length,addition,color};}
export function dispatchSnapshot(state,packetIds){const allowed=new Set(packetIds),sharedShift=state.shifts.find(s=>s.status==='active')||[...state.shifts].sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt))[0],all=state.deliveries.filter(d=>sharedShift&&d.shiftId===sharedShift.id).sort((a,b)=>(a.status==='active'?0:1)-(b.status==='active'?0:1)||Date.parse(a.enteredAt)-Date.parse(b.enteredAt));const value={version:1,capabilities:{batchRequests:true,routeRequests:true,colorReset:true,readyRequests:true},updatedAt:new Date().toISOString(),shiftSummary:sharedShift?{id:sharedShift.id,status:sharedShift.status,startedAt:sharedShift.startedAt,endedAt:sharedShift.endedAt||null,actualMiles:sharedShift.status==='finalized'?miles(sharedShift):null,completedOrders:all.filter(d=>d.status==='delivered'&&!d.recoveryOf).length,activeOrders:all.filter(d=>d.status==='active').length,heldOrders:all.filter(d=>d.scheduleHold&&d.status==='ready').length,runs:state.runs.filter(r=>r.shiftId===sharedShift.id).length,tasks:taskLabels(sharedShift.tasks||{})}:null,orders:[],commands:Object.values(state.dispatchCommandResults||{}).filter(c=>allowed.has(c.id)).slice(-10),omitted:0};for(const d of all){const row={readOnly:!allowed.has(d.dispatchId),driverCreated:!d.dispatchId,batchId:d.batchId||null,departedAt:d.departedAt||null,completedAt:d.completedAt||null,scheduledAt:d.scheduledAt||null};for(const k of ['id','dispatchId','dispatchGroupId','dispatchAddition','dispatchColor','batchId','batchPosition','batchLabel','status','enteredAt','readyAt','departedAt','completedAt','scheduledAt','hasColdItems','hasAlcohol','needsSignature','scheduleHold'])if(d[k]!=null)row[k]=d[k];for(const [k,max]of Object.entries({name:100,phone:40,address:350,ticket:30,notes:4000,coldItemDetails:500}))row[k]=String(d[k]||'').slice(0,max);row.items=cleanItems(d.items);value.orders.push(row);if(new TextEncoder().encode(JSON.stringify(value)).length>20000){value.orders.pop();value.omitted++;}}return value;}
export async function sealDispatchView(config,value,revision=Date.now()){const key=await crypto.subtle.importKey('raw',un64(config.key),'AES-GCM',false,['encrypt']),iv=crypto.getRandomValues(new Uint8Array(12));const bytes=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad(config.id,'status-'+revision,config.mode)},key,new TextEncoder().encode(JSON.stringify(value)));if(bytes.byteLength>24000)throw Error('Status view too large.');return {iv:b64(iv),ciphertext:b64(new Uint8Array(bytes)),revision};}
export async function openDispatchView(config,packet){const key=await crypto.subtle.importKey('raw',un64(config.key),'AES-GCM',false,['decrypt']);const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(packet.iv),additionalData:aad(config.id,'status-'+packet.revision,config.mode)},key,un64(packet.ciphertext));const value=JSON.parse(new TextDecoder().decode(bytes));if(value.version!==1||!Array.isArray(value.orders)||!Array.isArray(value.commands))throw Error('Invalid driver status view.');return value;}
export function reconcileDispatchColors(state){if(state.dispatchColorRuleVersion===2)return;for(const shift of state.shifts){const groups=new Map();for(const d of state.deliveries.filter(d=>d.shiftId===shift.id&&d.dispatchId)){const id=d.dispatchGroupId||d.dispatchId;if(!groups.has(id))groups.set(id,[]);groups.get(id).push(d);}const prior=[];for(const [id,orders] of [...groups.entries()].sort((a,b)=>Date.parse(a[1][0].enteredAt)-Date.parse(b[1][0].enteredAt))){const at=Date.parse(orders[0].enteredAt),active=prior.filter(g=>g.orders.some(d=>!['delivered','canceled'].includes(d.status)||d.completedAt&&Date.parse(d.completedAt)>at)),color=active.length?DISPATCH_COLORS[(DISPATCH_COLORS.indexOf(active.at(-1).color)+1)%4]:'orange';for(const d of orders)if(!['delivered','canceled'].includes(d.status))d.dispatchColor=color;const receipt=shift.dispatchReceipts?.find(r=>r.id===id);if(receipt&&orders.some(d=>!['delivered','canceled'].includes(d.status)))receipt.color=color;prior.push({orders,color});}}state.dispatchColorRuleVersion=2;}

function reorderDispatchedBatch(state,shift,packet,command,at){const members=state.deliveries.filter(d=>d.shiftId===shift.id&&d.batchId===command.batchId&&d.status!=='canceled'),ids=new Set(command.deliveryIds);const invalid=!members.length||members.length!==ids.size||members.some(d=>!ids.has(d.id)||!d.dispatchId||(packet.allowedDispatchIds&&!packet.allowedDispatchIds.includes(d.dispatchId))||!['pending','ready'].includes(d.status)||d.departedAt||state.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(d.id)));state.dispatchReceipts??=[];state.dispatchReceipts.push(packet.id);state.dispatchCommandResults??={};if(invalid){const message='Route not changed: the batch changed, contains other orders, or delivery has started.';state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'rejected',message,at};return {rejected:message};}command.deliveryIds.forEach((id,position)=>{Object.assign(members.find(d=>d.id===id),{batchPosition:position,routeCustomized:true,routeOrderSource:'manager'});});state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'reordered',message:'Route order updated. Due-soon scheduled deliveries still take priority.',at};return {reordered:members.length};}

function markDispatchedReady(state,shift,packet,command,at){
 const orders=command.deliveryIds.map(id=>state.deliveries.find(d=>d.id===id));
 const invalid=orders.some(d=>!d||d.shiftId!==shift.id||!d.dispatchId||d.dispatchPairId!==packet.pairId||!packet.allowedDispatchIds?.includes(d.dispatchId)||!['pending','ready'].includes(d.status)||d.departedAt);
 state.dispatchReceipts??=[];state.dispatchReceipts.push(packet.id);state.dispatchCommandResults??={};
 if(invalid){const message='Readiness not changed: an order is missing, belongs to another driver, or has started.';state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'rejected',message,at};return {rejected:message};}
 let changed=0;for(const d of orders)if(d.status==='pending'){d.status='ready';d.readyAt=Number.isFinite(packet.created_at)&&packet.created_at<=Date.parse(at)?new Date(Math.max(packet.created_at,Date.parse(d.enteredAt))).toISOString():at;d.readySource='dispatch-manual';if(command.hold&&d.scheduledAt){d.scheduleHold=true;d.scheduleHeldAt=at;}d.events??=[];d.events.push({type:'status-changed',from:'pending',to:'ready',at:d.readyAt,source:'dispatch'});changed++;}
 state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'ready',message:'Readiness updated on the driver’s app.',at};
 return {ready:changed,notifyReady:changed>0&&orders.some(d=>!d.scheduleHold)&&!state.runs.some(r=>r.shiftId===shift.id&&r.status==='active')};
}
